using System;using System.Linq;using System.Globalization;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime
{
 public static class MetaSettings
 {
  static void Edit(GameRuntime g,Action<GameState> edit,Action refresh){g.Act(s=>{var n=s.Copy();edit(n);n.Prestige.revision++;return n;});refresh();}
  static void Toggle(Transform p,GameRuntime g,string name,string label,bool value,Action<GameState> edit,Action refresh){var b=WorkshopUIFactory.Button(name,p,label+": "+(value?"An":"Aus"),()=>Edit(g,edit,refresh));b.interactable=g.Writable;}
  static void Number(Transform p,GameRuntime g,string name,string label,NumberData value,Action<GameState,NumberData> edit,Action refresh){WorkshopUIFactory.Label(name+"Label",p,label,14,44);var root=WorkshopUIFactory.Node(name,p,typeof(Image),typeof(InputField));WorkshopUIFactory.Size(root,54);root.GetComponent<Image>().color=new Color(.1f,.2f,.25f);var text=WorkshopUIFactory.Label("Value",root.transform,"",16);UnityEngine.Object.DestroyImmediate(text.GetComponent<LayoutElement>());WorkshopUIFactory.Fill(text.rectTransform);var f=root.GetComponent<InputField>();f.textComponent=text;f.text=value.m.ToString("R",CultureInfo.InvariantCulture)+"e"+value.e;f.interactable=g.Writable;f.onEndEdit.AddListener(v=>{try{var parsed=ScientificNumber.Parse(v).ToData();Edit(g,n=>edit(n,parsed),refresh);}catch(FormatException){}catch(ArgumentOutOfRangeException){}});}
  public static void Build(Transform parent,GameRuntime game,string id,Action refresh){var s=game.State;var m=s.Meta;if(MetaRules.Level(s,id)==0)return;
   if(id=="B04"){Number(parent,game,"ReserveINT","Absolutes INT-Sparziel",m.intReserve,(n,v)=>n.Meta.intReserve=v,refresh);WorkshopUIFactory.Label("RebuildOrder",parent,"Wiederkauf in gespeicherter Reihenfolge: "+string.Join(", ",m.rebuild),14,100);WorkshopUIFactory.Button("RebuildCheapest",parent,"Bekannte nach Preis sortieren",()=>Edit(game,n=>n.Meta.rebuild=PrestigeBalance.Nodes.Where(d=>n.Prestige.known.Contains(d.Id)).OrderBy(d=>d.Cost).Select(d=>d.Id).ToArray(),refresh));WorkshopUIFactory.Button("ClearRebuild",parent,"Wiederkaufplan leeren",()=>Edit(game,n=>n.Meta.rebuild=Array.Empty<string>(),refresh));foreach(string known in s.Prestige.known){string k=known;WorkshopUIFactory.Button("Rebuild-"+k,parent,(m.rebuild.Contains(k)?"Entfernen ":"Am Ende ergänzen ")+k,()=>Edit(game,n=>n.Meta.rebuild=n.Meta.rebuild.Contains(k)?n.Meta.rebuild.Where(x=>x!=k).ToArray():n.Meta.rebuild.Concat(new[]{k}).ToArray(),refresh));}}
   if(id=="B06"){Toggle(parent,game,"AutoAxiom","Automatisches Axiom (mindestens 5 Minuten Zyklus)",m.axiomAuto,ResetControls.ToggleAxiom,refresh);Number(parent,game,"AxiomMinimum","Mindestgewinn Axiome",m.axiomMinimum,(n,v)=>n.Meta.axiomMinimum=ScientificNumber.FromData(v).CompareTo(ScientificNumber.One)<0?ScientificNumber.One.ToData():v,refresh);WorkshopUIFactory.Label("AgentWaits",parent,"Job-Warteregeln gemeinsam mit dem Prestige-Agenten:",14,54);Toggle(parent,game,"AxiomWaitTraining","Training abwarten",s.Prestige.agentWaitTraining,n=>n.Prestige.agentWaitTraining=!n.Prestige.agentWaitTraining,refresh);Toggle(parent,game,"AxiomWaitResearch","Forschung abwarten",s.Prestige.agentWaitResearch,n=>n.Prestige.agentWaitResearch=!n.Prestige.agentWaitResearch,refresh);Toggle(parent,game,"AxiomWaitAnalysis","Analyse abwarten",s.Prestige.agentWaitAnalysis,n=>n.Prestige.agentWaitAnalysis=!n.Prestige.agentWaitAnalysis,refresh);Toggle(parent,game,"AxiomWaitCraft","Module abwarten",s.Prestige.agentWaitCrafting,n=>n.Prestige.agentWaitCrafting=!n.Prestige.agentWaitCrafting,refresh);}
   if(id=="C02"||id=="C03"){Number(parent,game,"ReserveData","Gemeinsames absolutes Daten-Sparziel",s.Prestige.dataReserve,(n,v)=>n.Prestige.dataReserve=v,refresh);}
   if(id=="C02"){Toggle(parent,game,"AutoAnalysis","Analyse wiederholen",m.analysisAuto,n=>n.Meta.analysisAuto=!n.Meta.analysisAuto,refresh);WorkshopUIFactory.Button("AnalysisRecipe",parent,"Analyse: "+ItemBalance.Analyses[m.analysisRecipe].Id,()=>Edit(game,n=>n.Meta.analysisRecipe=(n.Meta.analysisRecipe+1)%6,refresh));}
   if(id=="C03"){Toggle(parent,game,"AutoCraft","Fertigungsplaner",m.craftAuto,n=>n.Meta.craftAuto=!n.Meta.craftAuto,refresh);WorkshopUIFactory.Button("CraftRecipe",parent,"Rezept: "+ItemBalance.Items[Workshop.Index(m.craftRecipe)].Name,()=>Edit(game,n=>n.Meta.craftRecipe=ItemBalance.Items[(Workshop.Index(n.Meta.craftRecipe)+1)%ItemBalance.Items.Length].Id,refresh));WorkshopUIFactory.Button("CraftTarget",parent,"Zielbestand: "+m.craftTarget,()=>Edit(game,n=>{int[] a={1,5,10};n.Meta.craftTarget=a[(Array.IndexOf(a,n.Meta.craftTarget)+1)%3];},refresh));}
   if(id=="C04"){Toggle(parent,game,"AutoFusion","Fusionsplaner",m.fusionAuto,n=>n.Meta.fusionAuto=!n.Meta.fusionAuto,refresh);WorkshopUIFactory.Button("FusionTarget",parent,"Zielseltenheit: "+ItemBalance.Rarities[m.fusionTarget],()=>Edit(game,n=>n.Meta.fusionTarget=1+n.Meta.fusionTarget%5,refresh));foreach(var d in ItemBalance.Items){string k=d.Id;Toggle(parent,game,"Fuse-"+k,d.Name,m.fusionTypes.Contains(k),n=>n.Meta.fusionTypes=n.Meta.fusionTypes.Contains(k)?n.Meta.fusionTypes.Where(x=>x!=k).ToArray():n.Meta.fusionTypes.Concat(new[]{k}).ToArray(),refresh);}}
   if(id=="D04"){for(int i=0;i<3;i++){int phase=i;WorkshopUIFactory.Button("PhaseModel"+i,parent,new[]{"Neustart","Forschungsbeginn","Materialbeginn"}[i]+": "+(string.IsNullOrEmpty(m.modelPlan[i])?"Keine Auswahl":m.modelPlan[i]),()=>Edit(game,n=>{var ids=new[]{""}.Concat(MetaBalance.Models.Where((d,k)=>n.Meta.models[k]>=0).Select(d=>d.Id)).ToArray();n.Meta.modelPlan[phase]=ids[(Array.IndexOf(ids,n.Meta.modelPlan[phase])+1)%ids.Length];},refresh));}}
  }
 }
}
